 if(kind==='topic'){$('#dialog-title').textContent='Add a topic';const [si,ui]=($('#entry-form').dataset.parent||'0:0').split(':').map(Number);fields.innerHTML=`<label class="field-label">Topic name<input class="field-input" name="topic" required placeholder="e.g. Binary arithmetic"></label><input type="hidden" name="subjectIndex" value="${si}"><input type="hidden" name="unitIndex" value="${ui}">`}
 if(kind==='resource'){$('#dialog-title').textContent='Add a resource';fields.innerHTML=`<label class="field-label">Resource title<input class="field-input" name="title" required placeholder="e.g. Loops explained visually"></label>${selectTopic}<label class="field-label">Type<select class="field-input" name="type"><option value="video">Video lecture</option><option value="notes">Notes or PDF link</option><option value="practice">Practice link</option></select></label><label class="field-label">Link<input class="field-input" name="url" type="url" required placeholder="https://..."></label><label class="field-label">Credit name (optional)<input class="field-input" name="contributor" placeholder="Your name or nickname"></label>`}
 if(kind==='post'){$('#dialog-title').textContent='Write a community post';fields.innerHTML=`<label class="field-label">Post type<select class="field-input" name="kind"><option value="resource">Study tip</option><option value="lms">LMS help / workaround</option></select></label><label class="field-label">Title<input class="field-input" name="title" required maxlength="100"></label><label class="field-label">Details<textarea class="field-input" name="body" required maxlength="1000" placeholder="Keep it helpful and do not include private information."></textarea></label>`}
