function generatePlan(exam,date,minutes){const d=new Date(`${date}T12:00:00`),days=Math.ceil((d-new Date(new Date().toDateString()))/86400000);if(days<1){$('#plan-output').innerHTML='<p class="plan-note">Choose an exam date at least one day from today.</p>';return}const previousTasks=app.plan?.tasks||[],allTopics=topics(),doneTopicKeys=new Set(previousTasks.filter(t=>t.done).map(t=>{if(t.topicKey)return t.topicKey;const subject=t.kind.startsWith('Learn · ')?t.kind.slice('Learn · '.length):null,matches=allTopics.filter(x=>x.topic===t.title&&(!subject||x.subject===subject));return matches.length===1?matches[0].key:null}).filter(Boolean)),remain=allTopics.filter(t=>t.status!=='confident'),focusDays=Math.max(1,days-Math.max(1,Math.ceil(days*.2))),tasks=[];for(let i=0;i<days;i++){const batch=i<focusDays?remain.slice(Math.floor(i*remain.length/focusDays),Math.floor((i+1)*remain.length/focusDays)):[],dayDate=new Date();dayDate.setDate(dayDate.getDate()+i);const dayLabel=`Day ${i+1} · ${new Intl.DateTimeFormat('en-IN',{weekday:'short',month:'short',day:'numeric'}).format(dayDate)}`;if(batch.length)batch.forEach(t=>tasks.push({day:dayLabel,title:t.topic,topicKey:t.key,kind:'Learn · '+t.subject,minutes:Math.max(1,Math.floor(Number(minutes)/batch.length)),done:doneTopicKeys.has(t.key)}));else tasks.push({day:dayLabel,title:i>=focusDays?'Review, practise, or take a breather':'Catch up or revisit a tricky topic',kind:i>=focusDays?'Revision':'Catch-up buffer',minutes:Number(minutes),done:false})}app.plan={exam,date,days,minutes:Number(minutes),tasks,generatedOn:new Date().toISOString().slice(0,10)};save();renderPlan()}
let ticker=null,secondsLeft=1500;function updateTimer(){const m=Math.floor(secondsLeft/60),s=secondsLeft%60;$('#timer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function exportData(){const blob=new Blob([JSON.stringify(app,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chill-campus-my-study-data.json';a.click();URL.revokeObjectURL(a.href)}
function setHubTab(hub,tab){const root=$(`#${hub}-view`);if(!root)return;root.querySelectorAll('[data-hub-panel]').forEach(panel=>{const active=panel.dataset.hubPanel===tab;panel.hidden=!active;panel.classList.toggle('active-hub-panel',active)});root.querySelectorAll(`[data-hub-tab="${hub}"]`).forEach(button=>{const active=button.dataset.tab===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});const labels={planner:'Study planner',resources:'Resources & notes',quiz:'Quick quiz',flashcards:'Flashcards',revision:'Revision queue',community:'Class help',progress:'Progress'};$('#crumb-current').textContent=labels[tab]||tab}
function setView(view){const routes={planner:['study','planner'],resources:['study','resources'],quiz:['practice','quiz'],flashcards:['practice','flashcards'],revision:['practice','revision'],community:['more','community'],progress:['more','progress']},route=routes[view],parent=route?.[0]||view;document.querySelectorAll('.view').forEach(x=>x.classList.remove('active-view'));$(`#${parent}-view`)?.classList.add('active-view');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===parent));if(route)setHubTab(...route);else if(['study','practice','more'].includes(parent)){const defaults={study:'planner',practice:'quiz',more:'community'};setHubTab(parent,defaults[parent])}else{const names={dashboard:'Dashboard',syllabus:'My syllabus',session:'Study session',chat:'Study AI',profile:'Profile & settings'};$('#crumb-current').textContent=names[parent]||parent}window.scrollTo({top:0,behavior:'smooth'})}
function addChatMessage(message,role){const node=document.createElement('div');node.className=`chat-message ${role}`;if(role==='assistant'){const label=document.createElement('b');label.textContent='Study AI';const p=document.createElement('p');p.textContent=message;node.append(label,p)}else{const p=document.createElement('p');p.textContent=message;node.append(p)}$('#chat-messages').append(node);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;return node}
async function sendChatMessage(raw){const question=String(raw||'').trim();if(!question)return;addChatMessage(question,'user');if(!hasBackendConfig()){addChatMessage('Study AI is not connected yet. Add your Supabase project settings and deploy the secure AI function to enable real answers.','assistant');return}if(!backendUser){addChatMessage('Sign in to use Study AI. Your current study data stays private to your account.','assistant');updateAuthScreen();return}const submit=$('#chat-form button[type=submit]')||$('#chat-form button');if(submit)submit.disabled=true;const pending=addChatMessage('Thinking…','assistant');aiHistory.push({role:'user',content:question});try{const answer=await requestStudyAI('chat',question);pending.querySelector('p').textContent=answer;aiHistory.push({role:'assistant',content:answer});aiHistory=aiHistory.slice(-12)}catch(error){pending.querySelector('p').textContent=studyAiFailureMessage(error);const retry=document.createElement('button');retry.type='button';retry.className='text-button';retry.textContent='Retry';retry.addEventListener('click',()=>{pending.remove();aiHistory=aiHistory.filter(x=>!(x.role==='user'&&x.content===question));void sendChatMessage(question)});pending.append(retry)}finally{if(submit)submit.disabled=false}}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendChatMessage(new FormData(e.currentTarget).get('message'));e.currentTarget.reset()});document.querySelectorAll('[data-chat-prompt]').forEach(button=>button.addEventListener('click',()=>sendChatMessage(button.dataset.chatPrompt)));
document.addEventListener('click',e=>{const privateFile=e.target.closest('[data-open-upload]');if(privateFile){const popup=window.open('about:blank','_blank');if(!backendClient||!backendUser){popup?.close();return}if(popup)popup.opener=null;backendClient.storage.from('learner-uploads').createSignedUrl(privateFile.dataset.openUpload,60,{download:true}).then(({data,error})=>{if(error){popup?.close();return}if(popup)popup.location=data.signedUrl;else window.location.href=data.signedUrl});return}const tab=e.target.closest('[data-hub-tab]');if(tab){setHubTab(tab.dataset.hubTab,tab.dataset.tab);return}const guided=e.target.closest('[data-start-guided]');if(guided){const all=topics(),next=all.find(t=>t.status==='learning')||all.find(t=>t.status!=='confident')||all[0];if(next)$('#session-topic').value=next.key;setView('session');renderSessionResource();return}if(e.target.closest('#session-resource-button')){const topic=topics().find(t=>t.key===$('#session-topic').value);if(!topic)return;const match=app.resources.find(r=>r.topic===topic.topic&&r.subject===topic.subject);window.open(match?safeUrl(match.url):ytSearch(topic.topic),'_blank','noopener,noreferrer');return}if(e.target.closest('#session-practice-button')){const topic=topics().find(t=>t.key===$('#session-topic').value);$('#quiz-topic').value=questionBank.some(q=>q.topic===topic?.topic)?topic.topic:'all';setView('quiz');renderQuiz();return}const go=e.target.closest('[data-view],[data-goto]');if(go){setView(go.dataset.view||go.dataset.goto);return}const vid=e.target.closest('[data-find-video]');if(vid){window.open(ytSearch(vid.dataset.findVideo),'_blank','noopener');return}const sav=e.target.closest('[data-save-resource]');if(sav){const title=sav.dataset.saveResource;if(!app.savedResources.includes(title))app.savedResources.push(title);save();render();return}const helpful=e.target.closest('[data-helpful]');if(helpful){if(!app.helpful.includes(helpful.dataset.helpful)){app.helpful.push(helpful.dataset.helpful);award('resource',3);render()}return}const postHelpful=e.target.closest('[data-post-helpful]');if(postHelpful){const p=app.community.find(x=>x.id===postHelpful.dataset.postHelpful);if(p)p.helpful=(p.helpful||0)+1;save();renderCommunity();return}const addTopic=e.target.closest('[data-add-topic]');if(addTopic){$('#entry-form').dataset.parent=addTopic.dataset.addTopic;addDialog('topic');return}const addUnit=e.target.closest('[data-add-unit]');if(addUnit){$('#entry-form').dataset.subjectIndex=addUnit.dataset.addUnit;addDialog('unit');return}const edit=e.target.closest('[data-edit-subject]');if(edit){$('#entry-form').dataset.subjectIndex=edit.dataset.editSubject;addDialog('edit-subject')}});
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
