$('#entry-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),kind=e.currentTarget.dataset.kind;if(kind==='subject'){const name=f.get('name').trim(),unit=f.get('unit').trim(),items=f.get('topics').split(',').map(x=>x.trim()).filter(Boolean);if(name&&items.length)app.subjects.push({name,units:[{name:unit||'Topics',topics:items}]})}if(kind==='edit-subject'){const s=app.subjects[Number(e.currentTarget.dataset.subjectIndex)],name=f.get('name').trim();if(s&&name&&name!==s.name){const oldName=s.name;for(const unit of s.units)for(const topic of unit.topics){const oldKey=`${oldName}::${unit.name}::${topic}`,newKey=`${name}::${unit.name}::${topic}`;if(app.progress[oldKey]){if(!app.progress[newKey])app.progress[newKey]=app.progress[oldKey];delete app.progress[oldKey]}}app.resources.forEach(r=>{if(r.subject===oldName)r.subject=name});s.name=name}}if(kind==='unit'){const s=app.subjects[Number(f.get('subjectIndex'))],unit=f.get('unit').trim();if(s&&unit)s.units.push({name:unit,topics:[]})}if(kind==='topic'){const s=app.subjects[Number(f.get('subjectIndex'))],u=s?.units[Number(f.get('unitIndex'))],t=f.get('topic').trim();if(t&&u)u.topics.push(t)}if(kind==='resource'){const option=f.get('topic'),subject=e.currentTarget.querySelector('[name=topic] option:checked').dataset.subject,url=safeUrl(f.get('url'));if(url!=='#'){app.resources.push({title:f.get('title').trim(),topic:option,subject,type:f.get('type'),url,contributor:f.get('contributor').trim()||app.profile.name});award('resource',3)}}if(kind==='post'){const body=f.get('body').trim();if(/password|student\s*id|login\s*credential/i.test(body)){alert('Please remove passwords, student IDs, and credentials before sharing.');return}app.community.push({id:(globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`),kind:f.get('kind'),title:f.get('title').trim(),body,author:app.profile.name,helpful:0});award('post',3)}if(kind==='flashcard'){app.flashcards.push({front:f.get('front').trim(),back:f.get('back').trim()})}save();e.currentTarget.reset();$('#entry-dialog').close();render()});
$('#coach-form').addEventListener('submit',e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('question').trim(),topic=topics().find(t=>q.toLowerCase().includes(t.topic.toLowerCase().slice(0,Math.min(12,t.topic.length))));const response=topic?`Try this: break “${topic.topic}” into a definition, one small example, and a practice question. First, write what you already know in your own words. Then find a lecture or note for this topic in Resources. This starter coach uses study prompts; connect an AI service for generated explanations.`:'Try asking one small question at a time. For example: “Explain this in simpler words,” “Show a worked example,” or “What should I practise next?” Add the relevant topic to your syllabus or choose a resource to keep your study focused. This starter coach does not send your question to an AI service.';$('#coach-answer').innerHTML=`<b>Study coach suggestion</b><p>${esc(response)}</p>`});
