$('#resource-file').addEventListener('change',async e=>{const file=e.currentTarget.files?.[0];if(!file)return;const allowed=['application/pdf','text/plain','image/png','image/jpeg'];if(!allowed.includes(file.type)||file.size>10*1024*1024){$('#upload-status').textContent='Choose a PDF, TXT, PNG, or JPG file under 10 MB.';e.currentTarget.value='';return}if(!backendClient||!backendUser){$('#upload-status').textContent='Sign in to upload a private note.';e.currentTarget.value='';return}$('#upload-resource').disabled=true;$('#upload-status').textContent='Uploading privately…';try{const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-100),path=backendUser.id+'/'+crypto.randomUUID()+'-'+safeName;const {error}=await backendClient.storage.from('learner-uploads').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;app.resources.push({title:file.name.slice(0,140),topic:'',subject:'Personal note',type:'notes',storagePath:path,contributor:app.profile.name||'You'});save();render();$('#upload-status').textContent='Uploaded to your private notes.'}catch{$('#upload-status').textContent='Upload failed. Check your connection and try again.'}finally{$('#upload-resource').disabled=false;e.currentTarget.value=''}});
