$('#ai-quiz-button').addEventListener('click',async()=>{const selected=$('#quiz-topic').value,topic=selected==='all'?((topics().find(t=>t.status!=='confident')||topics()[0])?.topic):selected;if(!topic){$('#ai-quiz-status').textContent='Add a syllabus topic first.';return}$('#ai-quiz-button').disabled=true;$('#ai-quiz-status').textContent='Creating fresh questions…';try{const prompt='Create five varied multiple-choice questions for this syllabus topic: '+topic+'. Return JSON only, shaped as {"questions":[{"question":"...","options":["...","...","..."],"answerIndex":0,"explanation":"...","difficulty":"Easy"}]}. Include 3 or 4 options each and vary difficulty.';const raw=await requestStudyAI('quiz',prompt),parsed=JSON.parse(raw),items=Array.isArray(parsed.questions)?parsed.questions:[];const clean=items.slice(0,5).map(x=>{const options=Array.isArray(x.options)?x.options.filter(v=>typeof v==='string').slice(0,5):[],correct=Number(x.answerIndex);return{topic:topic,q:String(x.question||'').slice(0,500),options,correct,why:String(x.explanation||'Review the concept and try again.').slice(0,700)}}).filter(x=>x.q&&x.options.length>=2&&Number.isInteger(x.correct)&&x.correct>=0&&x.correct<x.options.length);if(!clean.length)throw new Error('invalid_quiz');aiQuizSet=clean;$('#quiz-topic').value=topic;renderQuiz();$('#ai-quiz-status').textContent='Fresh AI questions ready. Check each answer to see an explanation.'}catch(error){$('#ai-quiz-status').textContent=studyAiFailureMessage(error)}finally{$('#ai-quiz-button').disabled=false}});
$('#ai-flashcards-button').addEventListener('click',async()=>{const selected=$('#quiz-topic').value,topic=selected==='all'?((topics().find(t=>t.status!=='confident')||topics()[0])?.topic):selected;if(!topic){$('#ai-flashcards-status').textContent='Add a syllabus topic first.';return}$('#ai-flashcards-button').disabled=true;$('#ai-flashcards-status').textContent='Making a new deck…';try{const prompt='Create eight flashcards for this syllabus topic: '+topic+'. Return JSON only, shaped as {"cards":[{"question":"...","answer":"...","explanation":"..."}]}.';const raw=await requestStudyAI('flashcards',prompt),parsed=JSON.parse(raw),items=Array.isArray(parsed.cards)?parsed.cards:[];const cards=items.slice(0,8).map(x=>({front:String(x.question||'').slice(0,500),back:(String(x.answer||'')+'\n\nWhy: '+String(x.explanation||'')).slice(0,1500)})).filter(x=>x.front&&x.back);if(!cards.length)throw new Error('invalid_cards');app.flashcards.push(...cards);cardIndex=app.flashcards.length-cards.length;cardShowingAnswer=false;save();renderFlashcard();$('#ai-flashcards-status').textContent='Added '+cards.length+' AI flashcards to your deck.'}catch(error){$('#ai-flashcards-status').textContent=studyAiFailureMessage(error)}finally{$('#ai-flashcards-button').disabled=false}});$('#flip-card').addEventListener('click',()=>{cardShowingAnswer=!cardShowingAnswer;renderFlashcard()});$('#next-card').addEventListener('click',()=>{cardIndex++;cardShowingAnswer=false;renderFlashcard()});
