$('#ai-plan-button').addEventListener('click',async()=>{const f=new FormData($('#plan-form')),exam=String(f.get('exam')||'').trim(),date=String(f.get('date')||''),minutes=Number(f.get('minutes')||45);if(!exam||!date){$('#plan-output').innerHTML='<p class="plan-note">Add your exam name and date first.</p>';return}const days=Math.ceil((new Date(date+'T12:00:00')-new Date(new Date().toDateString()))/86400000);if(days<1){$('#plan-output').innerHTML='<p class="plan-note">Choose an exam date at least one day from today.</p>';return}$('#ai-plan-button').disabled=true;$('#plan-output').textContent='Study AI is building a realistic plan…';try{const syllabus=topics().filter(t=>t.status!=='confident').slice(0,24).map(t=>({subject:t.subject,topic:t.topic,status:t.status}));const prompt='Create an exam study schedule as JSON only. Exam: '+exam+'. Exam date: '+date+'. Days available: '+days+'. Daily minutes: '+minutes+'. Topics and confidence: '+JSON.stringify(syllabus)+'. Return {"tasks":[{"day":1,"topic":"...","minutes":20,"kind":"Learning","title":"..."}]}. Include learning, practice, revision and catch-up; keep total daily minutes at or below '+minutes+' and prioritize topics marked Learning.';const raw=await requestStudyAI('plan',prompt),parsed=JSON.parse(raw),items=Array.isArray(parsed.tasks)?parsed.tasks:[];const all=topics(),usedMinutes={},tasks=items.slice(0,Math.min(80,days*4)).map((x,i)=>{const dayNo=Math.min(days,Math.max(1,Number(x.day)||Math.floor(i/2)+1)),d=new Date();d.setDate(d.getDate()+dayNo-1);const title=String(x.title||x.topic||'Catch-up and review').slice(0,180),topic=String(x.topic||'').slice(0,160),match=all.find(t=>t.topic.toLowerCase()===topic.toLowerCase()),remaining=minutes-(usedMinutes[dayNo]||0),taskMinutes=Math.min(remaining,Math.max(0,Number(x.minutes)||20));if(taskMinutes<1)return null;usedMinutes[dayNo]=(usedMinutes[dayNo]||0)+taskMinutes;const rawKind=String(x.kind||'Learning'),kind=['Learning','Practice','Revision','Catch-up'].includes(rawKind)?rawKind:'Learning';return{day:'Day '+dayNo+' · '+new Intl.DateTimeFormat('en-IN',{weekday:'short',month:'short',day:'numeric'}).format(d),title,topicKey:match?.key,kind,minutes:taskMinutes,done:false}}).filter(Boolean);if(!tasks.length)throw new Error('invalid_plan');app.plan={exam,date,days,minutes,tasks,generatedOn:new Date().toISOString().slice(0,10),generatedByAI:true};save();renderPlan()}catch(error){$('#plan-output').textContent=studyAiFailureMessage(error)+' Your current plan is unchanged.'}finally{$('#ai-plan-button').disabled=false}});
document.addEventListener('change',e=>{if(e.target.matches('[data-plan-task]')){const i=Number(e.target.dataset.planTask);app.plan.tasks[i].done=e.target.checked;if(e.target.checked)award('task',5);save();renderPlan()}if(e.target.id==='leaderboard-optin'){app.leaderboard=e.target.checked;save();renderProgress()}});
window.addEventListener('online',()=>scheduleRemoteSave());
document.querySelectorAll('input[name="appearance"]').forEach(input=>input.addEventListener('change',e=>{if(!e.target.checked)return;app.appearance=e.target.value;document.body.dataset.appearance=app.appearance;document.querySelectorAll('.appearance-choice').forEach(choice=>choice.classList.toggle('selected',choice.querySelector('input').checked));const names={campus:'Campus mode',editorial:'Editorial mode',focus:'Focus studio'};$('#appearance-status').textContent=names[app.appearance]+' selected. Saved on this device.';save()}));
$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);app.profile={name:f.get('name').trim(),college:f.get('college').trim()};save();render();alert(backendUser?'Saved to your account.':'Saved on this device.')});$('#export-data').addEventListener('click',exportData);
$('#logout-button').addEventListener('click',async()=>{if(!confirm(backendUser?'Log out of Chill Campus.ai?':'Log out of the local preview?'))return;if(backendClient&&backendUser){const {error}=await backendClient.auth.signOut();if(error)authMessage('Could not sign out. Please try again.')}else{app.sessionActive=false;save();clearInterval(ticker);ticker=null;updateAuthScreen()}});
$('#auth-mode-toggle').addEventListener('click',()=>{const form=$('#auth-form'),signup=form.dataset.mode!=='signup';form.dataset.mode=signup?'signup':'signin';$('#auth-submit').textContent=signup?'Create account':'Sign in';$('#auth-title').textContent=signup?'Create your account':'Sign in to Chill Campus.ai';$('#auth-mode-toggle').textContent=signup?'Already have an account? Sign in':'New here? Create an account';authMessage('')});
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();if(!backendClient)return;const f=new FormData(e.currentTarget),email=String(f.get('email')||'').trim(),password=String(f.get('password')||''),signup=e.currentTarget.dataset.mode==='signup';if(password.length<8){authMessage('Use a password with at least 8 characters.');return}$('#auth-submit').disabled=true;authMessage(signup?'Creating your account…':'Signing in…');try{const result=signup?await backendClient.auth.signUp({email,password,options:{emailRedirectTo:location.href.split('#')[0]}}):await backendClient.auth.signInWithPassword({email,password});if(result.error)throw result.error;if(signup&&!result.data.session)authMessage('Check your email to confirm your account, then come back here to sign in.');else authMessage('')}catch(error){authMessage(authFailureMessage(error,signup))}finally{$('#auth-submit').disabled=false}});
$('#auth-reset').addEventListener('click',async()=>{const email=$('#auth-form [name=email]').value.trim();if(!email){authMessage('Enter your email address first.');return}const {error}=await backendClient.auth.resetPasswordForEmail(email,{redirectTo:location.href.split('#')[0]});authMessage(error?'Could not send a reset email. Try again later.':'If an account exists for that email, a reset link is on its way.')});
$('#demo-sign-in').addEventListener('click',()=>{app.sessionActive=true;save();updateAuthScreen();setView('dashboard')});
$('#session-topic').addEventListener('change',renderSessionResource);$('#session-length').addEventListener('change',()=>{if(!ticker){secondsLeft=Number($('#session-length').value)*60;updateTimer()}});$('#timer-start').addEventListener('click',()=>{if(ticker){clearInterval(ticker);ticker=null;$('#timer-start').textContent='Resume focus';return}$('#timer-start').textContent='Pause';ticker=setInterval(()=>{secondsLeft--;updateTimer();if(secondsLeft<=0){clearInterval(ticker);ticker=null;$('#timer-start').textContent='Start focus';$('#session-complete').innerHTML='<b>Session complete ✨</b> Step 3: check in with your confidence below.';award('session',10)}},1000)});$('#timer-reset').addEventListener('click',()=>{clearInterval(ticker);ticker=null;secondsLeft=Number($('#session-length').value)*60;updateTimer();$('#timer-start').textContent='Start focus'});document.querySelectorAll('[data-confidence]').forEach(b=>b.addEventListener('click',()=>{const key=$('#session-topic').value;if(!key)return;const status=b.dataset.confidence;app.progress[key]={status,updatedAt:new Date().toISOString()};if(status==='confident')award('topic',10);save();if(app.plan)generatePlan(app.plan.exam,app.plan.date,app.plan.minutes);else render();$('#session-complete').textContent=status==='confident'?'Nice work. Your topic is marked confident.':'Added to your revision queue. A second pass is part of learning.'}));
